<?php
declare(strict_types=1);
require dirname(__DIR__).'/api/lib.php';require dirname(__DIR__).'/api/supplier-catalog.php';require dirname(__DIR__).'/api/supplier-link.php';require dirname(__DIR__).'/api/supplier-session.php';require dirname(__DIR__).'/api/supplier-import.php';
if(config()['admin_email']!=='test-admin@example.test')throw new RuntimeException('Use somente banco de teste');
function import_check(bool $ok,string $message):void {if(!$ok)throw new RuntimeException('FAILED '.$message);echo 'PASS '.$message.PHP_EOL;}
$url='https://meudropbrasil.com/produto/fixture-import-simple/';$p=['title'=>'Fixture de importação simples','sku'=>'','cost'=>2600,'stock'=>null,'availability'=>'unknown','gtin'=>'','sourceUrl'=>$url];$before=setting('supplier_catalog','[]');
try{$result=supplier_import_link($url,fn()=>['products'=>[$p],'authenticatedSupplier'=>true]);import_check($result['imported']===true&&$result['product']['cost']===2600,'one import action persists a valid product');import_check($result['product']['skuOrigin']==='internal'&&$result['product']['supplierSku']===null&&str_starts_with($result['product']['sku'],'SD-'),'generated code is internal and never claimed as supplier SKU');$count=count(supplier_catalog());$second=supplier_import_link($url,fn()=>['products'=>[$p]]);import_check(count(supplier_catalog())===$count&&$second['product']['sku']===$result['product']['sku'],'repeat import updates same internal code');$old=setting('supplier_catalog');$bad=$p;$bad['cost']=null;$blocked=false;try{supplier_import_link($url,fn()=>['products'=>[$bad],'partial'=>true]);}catch(SupplierLinkException){$blocked=true;}import_check($blocked&&setting('supplier_catalog')===$old,'missing price never falls back to saved cost or overwrites a product');$bad=$p;$bad['sourceUrl']='https://meudropbrasil.com/produto/outro/';$blocked=false;try{supplier_import_link($url,fn()=>['products'=>[$bad]]);}catch(SupplierLinkException){$blocked=true;}import_check($blocked,'mismatched source not automatically imported');$blocked=false;try{supplier_import_link($url,fn()=>['products'=>[$p,$p]]);}catch(SupplierLinkException){$blocked=true;}import_check($blocked,'ambiguous product list not silently imported');
}finally{set_setting('supplier_catalog',$before);}
